import {
  Body,
  Controller,
  Delete,
  Get,
  HttpCode,
  HttpStatus,
  Param,
  Post,
  Query,
} from '@nestjs/common';
import { createUuidV4Pipe } from '../../common/pipes/uuid-v4.pipe';
import { CreateDealDto, DealListQueryDto, UpdateDealDto } from './dto';
import { DealService } from './deal.service';

@Controller('deals')
export class DealController {
  constructor(private readonly dealService: DealService) {}

  @Post()
  create(@Body() createDealDto: CreateDealDto) {
    return this.dealService.createDeal(createDealDto);
  }

  @Get()
  findAll(@Query() query: DealListQueryDto) {
    return this.dealService.getDeals(query);
  }

  @Get(':id')
  findOne(@Param('id', createUuidV4Pipe()) id: string) {
    return this.dealService.getDealById(id);
  }

  @Post(':id')
  update(
    @Param('id', createUuidV4Pipe()) id: string,
    @Body() updateDealDto: UpdateDealDto,
  ) {
    return this.dealService.updateDeal(id, updateDealDto);
  }

  @Delete(':id')
  @HttpCode(HttpStatus.NO_CONTENT)
  remove(@Param('id', createUuidV4Pipe()) id: string): Promise<void> {
    return this.dealService.removeDeal(id);
  }
}
import { HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactService } from '../contact/contact.service';
import { CompanyEntity } from '../company/company.entity';
import { DealRepository } from './deal.repository';
import { DealEntity } from './deal.entity';
import {
  CreateDealDto,
  DealContactLinkInputDto,
  DealListQueryDto,
  UpdateDealDto,
} from './dto';

type DealCompanySummary = Pick<
  CompanyEntity,
  'id' | 'name' | 'status' | 'industry'
>;

type DealContactSummary = {
  id: string;
  name: string;
  email: string | null;
  phone: string | null;
  role: string | null;
};

export type DealContactLinkResponse = {
  contactId: string;
  role: string | null;
  isPrimary: boolean;
  contact: DealContactSummary | null;
};

export type DealResponse = DealEntity & {
  company: DealCompanySummary;
  primaryContact: DealContactSummary | null;
  contactLinks: DealContactLinkResponse[];
};

export type DealDetailResponse = DealResponse;

type NormalizedDealContactLink = {
  contactId: string;
  role: string | null;
};

type DealContactLinksRow = {
  dealId: string;
  contactId: string;
  role: string | null;
  contactIdValue: string | null;
  contactName: string | null;
  contactEmail: string | null;
  contactPhone: string | null;
  contactRole: string | null;
};

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealResponse> {
    await this.companyService.getCompanyById(dto.companyId);

    const normalizedLinks = this.resolveCreateContactLinks(dto);
    await this.validateContactsForCompany(
      normalizedLinks.contactLinks.map((link) => link.contactId),
      dto.companyId,
    );

    const { contactLinks, primaryContactId, ...dealFields } = dto;

    void contactLinks;
    void primaryContactId;

    const persistedDeal = await this.dealRepository.manager.transaction(
      async (entityManager) => {
        const dealRepository = entityManager.getRepository(DealEntity);

        const deal = dealRepository.create({
          ...dealFields,
          primaryContactId: normalizedLinks.primaryContactId,
          stage: dto.stage ?? 'lead',
          expectedCloseDate: dto.expectedCloseDate ?? null,
        });

        const savedDeal = await dealRepository.save(deal);

        if (normalizedLinks.contactLinks.length > 0) {
          await entityManager
            .createQueryBuilder()
            .insert()
            .into('deal_contacts')
            .values(
              normalizedLinks.contactLinks.map((link) => ({
                dealId: savedDeal.id,
                contactId: link.contactId,
                role: link.role,
              })),
            )
            .execute();
        }

        return savedDeal;
      },
    );

    return this.getDealById(persistedDeal.id);
  }

  async getDeals(query: DealListQueryDto) {
    const page = await this.dealRepository.findWithFilter(query);
    const hydratedItems = await this.hydrateDeals(page.items);

    return {
      ...page,
      items: hydratedItems,
    };
  }

  async getDealById(id: string): Promise<DealDetailResponse> {
    const deal = await this.getDealEntityById(id);
    const hydratedDeals = await this.hydrateDeals([deal]);
    return hydratedDeals[0];
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealResponse> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const existingDeal = await this.getDealEntityById(id);

    const targetCompanyId = dto.companyId ?? existingDeal.companyId;
    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.companyService.getCompanyById(dto.companyId);
    }

    const existingLinks = await this.getRawLinksByDealIds([id]);
    const hasContactLinkMutation =
      Object.prototype.hasOwnProperty.call(dto, 'contactLinks') ||
      Object.prototype.hasOwnProperty.call(dto, 'primaryContactId');

    const nextLinks = hasContactLinkMutation
      ? this.resolveUpdatedContactLinks(
          dto,
          existingDeal.primaryContactId,
          existingLinks[id] ?? [],
        )
      : {
          primaryContactId: existingDeal.primaryContactId,
          contactLinks: (existingLinks[id] ?? []).map((link) => ({
            contactId: link.contactId,
            role: link.role,
          })),
        };

    await this.validateContactsForCompany(
      nextLinks.contactLinks.map((link) => link.contactId),
      targetCompanyId,
    );

    const { contactLinks, primaryContactId, ...dealPatch } = dto;

    void contactLinks;
    void primaryContactId;

    await this.dealRepository.manager.transaction(async (entityManager) => {
      const dealRepository = entityManager.getRepository(DealEntity);

      const updatedDeal = dealRepository.merge(existingDeal, {
        ...dealPatch,
        primaryContactId: nextLinks.primaryContactId,
        stage: dto.stage ?? existingDeal.stage,
        expectedCloseDate: Object.prototype.hasOwnProperty.call(
          dto,
          'expectedCloseDate',
        )
          ? (dto.expectedCloseDate ?? null)
          : existingDeal.expectedCloseDate,
      });

      await dealRepository.save(updatedDeal);

      if (hasContactLinkMutation) {
        await entityManager
          .createQueryBuilder()
          .delete()
          .from('deal_contacts')
          .where('"dealId" = :dealId', { dealId: id })
          .execute();

        if (nextLinks.contactLinks.length > 0) {
          await entityManager
            .createQueryBuilder()
            .insert()
            .into('deal_contacts')
            .values(
              nextLinks.contactLinks.map((link) => ({
                dealId: id,
                contactId: link.contactId,
                role: link.role,
              })),
            )
            .execute();
        }
      }
    });

    return this.getDealById(id);
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealEntityById(id);
    await this.dealRepository.softDelete(id);
  }

  private async getDealEntityById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Deal with ID ${id} not found`,
        details: {
          resource: 'Deal',
          id,
        },
      });
    }

    return deal;
  }

  private resolveCreateContactLinks(dto: CreateDealDto): {
    primaryContactId: string | null;
    contactLinks: NormalizedDealContactLink[];
  } {
    const normalizedContactLinks = this.normalizeContactLinks(
      dto.contactLinks ?? [],
      'contactLinks',
    );

    const primaryContactId = dto.primaryContactId ?? null;

    this.validatePrimaryContactMembership(
      primaryContactId,
      normalizedContactLinks,
    );

    return {
      primaryContactId,
      contactLinks: normalizedContactLinks,
    };
  }

  private resolveUpdatedContactLinks(
    dto: UpdateDealDto,
    currentPrimaryContactId: string | null,
    currentLinks: DealContactLinkResponse[],
  ): {
    primaryContactId: string | null;
    contactLinks: NormalizedDealContactLink[];
  } {
    const currentNormalizedLinks = currentLinks.map((link) => ({
      contactId: link.contactId,
      role: link.role,
    }));

    const hasContactLinks = Object.prototype.hasOwnProperty.call(
      dto,
      'contactLinks',
    );
    const hasPrimaryContactId = Object.prototype.hasOwnProperty.call(
      dto,
      'primaryContactId',
    );

    const nextLinks = hasContactLinks
      ? this.normalizeContactLinks(dto.contactLinks ?? [], 'contactLinks')
      : currentNormalizedLinks;

    let nextPrimaryContactId = currentPrimaryContactId;

    if (hasPrimaryContactId) {
      nextPrimaryContactId = dto.primaryContactId ?? null;
    }

    if (hasContactLinks && !hasPrimaryContactId) {
      const nextLinkIds = new Set(nextLinks.map((link) => link.contactId));
      if (!nextPrimaryContactId || !nextLinkIds.has(nextPrimaryContactId)) {
        nextPrimaryContactId = null;
      }
    }

    this.validatePrimaryContactMembership(nextPrimaryContactId, nextLinks);

    return {
      primaryContactId: nextPrimaryContactId,
      contactLinks: nextLinks,
    };

