        FROM "deals"
        WHERE "name" LIKE 'Edge Deal%'
          AND NOT EXISTS (
            SELECT 1
            FROM "deal_contacts" dealContact
            WHERE dealContact."dealId" = "deals"."id"
          )
      `,
    );
    const [{ count: nullExpectedCloseCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Edge Deal%'
          AND "expectedCloseDate" IS NULL
      `,
    );

    expect(companyCount).toBe(25);
    expect(emptyCompanyCount).toBe(1);
    expect(nullFieldCount).toBe(1);
    expect(longNameCompanyCount).toBeGreaterThanOrEqual(1);
    expect(maxLengthRoleCount).toBeGreaterThanOrEqual(1);
    expect(orphanCount).toBe(0);
    expect(nullDealContactCount).toBeGreaterThanOrEqual(1);
    expect(nullExpectedCloseCount).toBeGreaterThanOrEqual(1);
  });
});

