import { faker } from '@faker-js/faker';
import {
  CompanyEntity,
  CompanyStatus,
  Industry,
} from '../../../modules/company/company.entity';
import { ContactEntity } from '../../../modules/contact/contact.entity';
import { DealEntity } from '../../../modules/deal/deal.entity';
import { buildCompany } from '../factories/company.factory';
import { buildContact } from '../factories/contact.factory';
import { buildDeal } from '../factories/deal.factory';
import { SeedContext, SeedScenario } from '../seed.types';
import {
  cleanupCompaniesByPrefixes,
  distributeRecentDate,
} from '../seed.utils';

const DEMO_PREFIX = 'Demo Seed Company';
const STATUSES = [
  CompanyStatus.ACTIVE,
  CompanyStatus.INACTIVE,
  CompanyStatus.PENDING,
] as const;
const INDUSTRIES = [
  Industry.TECHNOLOGY,
  Industry.FINANCE,
  Industry.MANUFACTURING,
  Industry.RETAIL,
  Industry.OTHER,
] as const;
const DEAL_STAGES = [
  'lead',
  'qualified',
  'proposal',
  'negotiation',
  'won',
] as const;

type DemoCompanyRecord = {
  company: CompanyEntity;
  contactIds: string[];
};

const createDemoCompanies = async ({ dataSource, now }: SeedContext) => {
  const companyRepository = dataSource.getRepository(CompanyEntity);
  const contactRepository = dataSource.getRepository(ContactEntity);
  const dealRepository = dataSource.getRepository(DealEntity);

  let contactsCreated = 0;
  let dealsCreated = 0;
  const companyRecords: DemoCompanyRecord[] = [];

  await cleanupCompaniesByPrefixes({ dataSource, now }, [DEMO_PREFIX]);

  for (let companyIndex = 0; companyIndex < 10; companyIndex += 1) {
    const companyName = `${DEMO_PREFIX} ${String(companyIndex + 1).padStart(2, '0')}`;
    const company = await companyRepository.save(
      companyRepository.create(
        buildCompany({
          name: companyName,
          status: STATUSES[companyIndex % STATUSES.length],
          industry: INDUSTRIES[companyIndex % INDUSTRIES.length],
          lastContactedAt: distributeRecentDate(now, companyIndex, 10),
          email: `demo-company-${companyIndex + 1}@baseline.local`,
        }),
      ),
    );

    const contactIds: string[] = [];
    const contactsForCompany = 2 + (companyIndex % 4);

    for (
      let contactIndex = 0;
      contactIndex < contactsForCompany;
      contactIndex += 1
    ) {
      contactsCreated += 1;

      const contact = await contactRepository.save(
        contactRepository.create(
          buildContact({
            name: faker.person.fullName(),
            lastContactedAt: distributeRecentDate(
              now,
              companyIndex + contactIndex,
              14,
            ),
            email: `demo-contact-${companyIndex + 1}-${contactIndex + 1}@baseline.local`,
            role: [
              'Decision Maker',
              'User',
              'Finance Reviewer',
              'Technical Buyer',
            ][contactIndex % 4],
          }),
        ),
      );

      await dataSource.query(
        `
          INSERT INTO "contact_companies" ("contactId", "companyId", "isPrimary")
          VALUES ($1, $2, true)
          ON CONFLICT ("contactId", "companyId") DO UPDATE
            SET "isPrimary" = EXCLUDED."isPrimary"
        `,
        [contact.id, company.id],
      );

      contactIds.push(contact.id);
    }

    companyRecords.push({
      company,
      contactIds,
    });
  }

  const primaryCompanyRecord = companyRecords[0];
  const secondaryCompanyRecord = companyRecords[1];
  const crossLinkedContactId = primaryCompanyRecord?.contactIds[0];

  if (crossLinkedContactId && secondaryCompanyRecord?.company.id) {
    await dataSource.query(
      `
        INSERT INTO "contact_companies" ("contactId", "companyId", "isPrimary")
        VALUES ($1, $2, false)
        ON CONFLICT ("contactId", "companyId") DO NOTHING
      `,
      [crossLinkedContactId, secondaryCompanyRecord.company.id],
    );
  }

  for (const [index, companyRecord] of companyRecords.entries()) {
    const isMultiContactDeal =
      index === 1 && companyRecord.contactIds.length >= 3;
    const linkedContactIds = isMultiContactDeal
      ? companyRecord.contactIds.slice(0, 3)
      : [];
    const contactId = isMultiContactDeal
      ? linkedContactIds[0]
      : index % 3 === 0
        ? null
        : (companyRecord.contactIds[0] ?? null);

    const deal = await dealRepository.save(
      dealRepository.create(
        buildDeal({
          companyId: companyRecord.company.id,
          primaryContactId: contactId,
          name: `Demo Deal ${String(index + 1).padStart(2, '0')}`,
          value: 5000 + index * 1750,
          stage: DEAL_STAGES[index % DEAL_STAGES.length],
          expectedCloseDate:
            index % 4 === 0 ? null : distributeRecentDate(now, index + 2, 18),
        }),
      ),
    );

    if (isMultiContactDeal) {
      await dataSource.query(
        `
          INSERT INTO "deal_contacts" ("dealId", "contactId", "role")
          VALUES
            ($1, $2, 'decision-maker'),
            ($1, $3, 'legal reviewer'),
            ($1, $4, 'it lead')
          ON CONFLICT ("dealId", "contactId") DO NOTHING
        `,
        [
          deal.id,
          linkedContactIds[0],
          linkedContactIds[1],
          linkedContactIds[2],
        ],
      );
    } else if (contactId) {
      await dataSource.query(
        `
          INSERT INTO "deal_contacts" ("dealId", "contactId", "role")
          VALUES ($1, $2, NULL)
          ON CONFLICT ("dealId", "contactId") DO NOTHING
        `,
        [deal.id, contactId],
      );
    }

    dealsCreated += 1;
  }

  return {
    contactsCreated,
    dealsCreated,
  };
};

export const demoSeedScenario: SeedScenario = {
