                  ? undefined
                  : distributeRecentDate(now, companyIndex + contactIndex, 40),
            }),
          ),
        );

        await dataSource.query(
          `
            INSERT INTO "contact_companies" ("contactId", "companyId", "isPrimary")
            VALUES ($1, $2, true)
            ON CONFLICT ("contactId", "companyId") DO UPDATE
              SET "isPrimary" = EXCLUDED."isPrimary"
          `,
          [contact.id, company.id],
        );

        companyContactIds.push(contact.id);
      }

      contactIdsByCompanyId[company.id] = companyContactIds;
    }

    let dealsCreated = 0;

    for (const [companyIndex, company] of savedCompanies
      .slice(0, 10)
