      const isNullExpectedCloseDateDeal =
        companyIndex === 1 || companyIndex === 6;

      const deal = await dealRepository.save(
        dealRepository.create(
          buildDeal({
            companyId: company.id,
            primaryContactId: isNullContactDeal
              ? null
              : (companyContactIds[0] ?? null),
            name: `Edge Deal ${String(companyIndex + 1).padStart(2, '0')}`,
            value: 2500 + companyIndex * 900,
            stage: EDGE_DEAL_STAGES[companyIndex % EDGE_DEAL_STAGES.length],
            expectedCloseDate: isNullExpectedCloseDateDeal
              ? null
              : distributeRecentDate(now, companyIndex + 8, 25),
          }),
        ),
      );

      if (!isNullContactDeal && companyContactIds[0]) {
        await dataSource.query(
          `
            INSERT INTO "deal_contacts" ("dealId", "contactId", "role")
            VALUES ($1, $2, NULL)
            ON CONFLICT ("dealId", "contactId") DO NOTHING
          `,
          [deal.id, companyContactIds[0]],
        );
      }

      dealsCreated += 1;
    }

    return {
      scenario: 'edge-case',
