import { NestFactory } from '@nestjs/core';
import { ValidationPipe, Logger } from '@nestjs/common';
import { AppModule } from './app.module';
import { HttpExceptionFilter } from './common/filter/http-exception.filter';
import { createValidationException } from './common/errors/validation-exception.factory';

async function bootstrap() {
  const logger = new Logger('Bootstrap');

  const app = await NestFactory.create(AppModule);

  app.setGlobalPrefix('api');
  app.enableCors();

  app.useGlobalFilters(new HttpExceptionFilter());

  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
      exceptionFactory: createValidationException,
    }),
  );

  const port =
    process.env.PORT ?? process.env.CRM_BASELINE_BACKEND_PORT ?? 3101;
  await app.listen(port);

  logger.log(`🚀 Application is running on: http://localhost:${port}/api`);
}

void bootstrap();
import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
} from '@nestjs/common';
import { Request, Response } from 'express';
import { AppExceptionPayload } from '../errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../errors/error-codes';

type ExceptionResponsePayload = {
  code?: string;
  message?: string | string[];
  details?: unknown;
};

const isExceptionResponsePayload = (
  value: unknown,
): value is ExceptionResponsePayload => {
  return typeof value === 'object' && value !== null;
};

@Catch(HttpException)
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: HttpException, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    // Get the HTTP status code from the exception (e.g., 400, 404, 500)
    const status = exception.getStatus();

    // Get the detailed response content from the exception
    const exceptionResponse: unknown = exception.getResponse();
    const payload = isExceptionResponsePayload(exceptionResponse)
      ? exceptionResponse
      : undefined;

    // Extract error message
    const message = payload?.message ? payload.message : exception.message;
    const normalizedMessage = Array.isArray(message) ? message[0] : message;
    const code = payload?.code ?? defaultErrorCode(status);
    const details = payload?.details;

    response.status(status).json({
      success: false,
      statusCode: status,
      code,
      message: normalizedMessage,
      details,
      timestamp: new Date().toISOString(),
      path: request.url,
    });
  }
}

function defaultErrorCode(status: number): AppExceptionPayload['code'] {
  const errorCodeByStatus: Partial<
    Record<number, AppExceptionPayload['code']>
  > = {
    [HttpStatus.BAD_REQUEST]: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
    [HttpStatus.NOT_FOUND]: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
    [HttpStatus.UNPROCESSABLE_ENTITY]: BUSINESS_ERROR_CODES.IMMUTABLE_FIELD,
    [HttpStatus.CONFLICT]: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
  };

  return errorCodeByStatus[status] ?? BUSINESS_ERROR_CODES.VALIDATION_ERROR;
}
import { HttpStatus, ValidationError } from '@nestjs/common';
import { AppException } from './app-exception';
import { BUSINESS_ERROR_CODES } from './error-codes';

type FormattedValidationError = {
  field: string;
  messages: string[];
};

export function createValidationException(errors: ValidationError[]) {
  const formattedErrors = flattenValidationErrors(errors);
  const firstMessage =
    formattedErrors[0]?.messages[0] ?? 'Request validation failed.';

  return new AppException({
    statusCode: HttpStatus.BAD_REQUEST,
    code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
    message: firstMessage,
    details: {
      errors: formattedErrors,
    },
  });
}

function flattenValidationErrors(
  errors: ValidationError[],
  parentPath?: string,
): FormattedValidationError[] {
  return errors.flatMap((error) => {
    const field = parentPath
      ? `${parentPath}.${error.property}`
      : error.property;
    const messages = error.constraints ? Object.values(error.constraints) : [];
    const currentError = messages.length > 0 ? [{ field, messages }] : [];
    const childErrors = error.children
      ? flattenValidationErrors(error.children, field)
      : [];

    return [...currentError, ...childErrors];
  });
}

const API_BASE_PATH = '/api';

// Thrown by request() for both network failures (status undefined) and non-2xx
// HTTP responses (status set). isTransportError() below is the single source of
// truth for "infra-level failure the global interceptor should toast" vs.
// "business error the calling page should handle and display itself".
export class RequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'RequestError';
    this.status = status;
  }
}

// Network failures (fetch itself rejected, no HTTP response at all) and 5xx
// server errors aren't meaningful to a specific page/action, so the global
// interceptor (see App.jsx) shows a generic toast for these. Every other
// status (400/401/403/404/409/422/...) is treated as a business error and
// left to the calling component to interpret and display.
export function isTransportError(error) {
  return !error?.status || error.status >= 500;
}

function buildUrl(path, query) {
  const url = new URL(`${API_BASE_PATH}${path}`, window.location.origin);

  if (query) {
    Object.entries(query).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        url.searchParams.set(key, value);
      }
    });
  }

  return `${url.pathname}${url.search}`;
}

// vite.config.js proxies /api/* to CRM_BASELINE_API_ORIGIN (backend mounts everything
// under app.setGlobalPrefix('api')), so callers pass paths like '/companies' and this
// prepends the /api prefix + serializes the `query` object as a querystring.
export async function request(path, { query, headers, ...options } = {}) {
  let response;

  try {
    response = await fetch(buildUrl(path, query), {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
    });
  } catch {
    throw new RequestError('Network error, please check your connection and try again.', undefined);
  }

  const text = await response.text();
  const data = text ? JSON.parse(text) : null;

  if (!response.ok) {
    const message = data?.message || response.statusText || 'Request failed';
    throw new RequestError(Array.isArray(message) ? message.join(', ') : message, response.status);
  }

  return data;
}

import { MutationCache, QueryCache, QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { enqueueSnackbar, SnackbarProvider } from 'notistack';
import { RouterProvider } from 'react-router-dom';

// project imports
import { isTransportError } from 'api/request';
import { RouteAccessProvider } from 'contexts/RouteAccessContext';
import router from 'routes';
import ThemeCustomization from 'themes';

// Transport-level failures (network errors, 5xx) aren't tied to a specific page/action,
// so they're toasted here once. Business errors (4xx) are left for the calling
// component to interpret and display (see isTransportError in api/request.js).
function handleTransportError(error) {
  if (isTransportError(error)) {
    enqueueSnackbar(error?.message || 'Something went wrong, please try again later.', { variant: 'error' });
  }
}

const queryClient = new QueryClient({
  queryCache: new QueryCache({ onError: handleTransportError }),
  mutationCache: new MutationCache({ onError: handleTransportError }),
});

// ==============================|| APP - THEME, ROUTER, LOCAL ||============================== //

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeCustomization>
        <SnackbarProvider maxSnack={3} anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}>
          <RouteAccessProvider>
            <RouterProvider router={router} />
          </RouteAccessProvider>
        </SnackbarProvider>
      </ThemeCustomization>
    </QueryClientProvider>
  );
}
