const DEAL_INITIAL_STAGE_SET = new Set<string>(DEAL_INITIAL_STAGES);

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealResponse> {
    await this.companyService.getCompanyById(dto.companyId);

    const initialStage = this.resolveInitialStage(dto.stage);

    const normalizedLinks = this.resolveCreateContactLinks(dto);
    await this.validateContactsForCompany(
      normalizedLinks.contactLinks.map((link) => link.contactId),
      dto.companyId,
    );

    const { contactLinks, primaryContactId, ...dealFields } = dto;

    void contactLinks;
    void primaryContactId;

    const persistedDeal = await this.dealRepository.manager.transaction(
      async (entityManager) => {
        const dealRepository = entityManager.getRepository(DealEntity);

        const deal = dealRepository.create({
          ...dealFields,
          primaryContactId: normalizedLinks.primaryContactId,
          stage: initialStage,
          expectedCloseDate: dto.expectedCloseDate ?? null,
        });

        const savedDeal = await dealRepository.save(deal);

        if (normalizedLinks.contactLinks.length > 0) {
          await entityManager
            .createQueryBuilder()
            .insert()
            .into('deal_contacts')
            .values(
              normalizedLinks.contactLinks.map((link) => ({
                dealId: savedDeal.id,
                contactId: link.contactId,
                role: link.role,
              })),
            )
            .execute();
        }

        return savedDeal;
      },
    );

    return this.getDealById(persistedDeal.id);
  }

  async getDeals(query: DealListQueryDto) {
    const stage = query.stage
      ? this.resolveRequestedStage(query.stage)
      : undefined;
    const page = await this.dealRepository.findWithFilter({
      ...query,
      stage,
    });
    const hydratedItems = await this.hydrateDeals(page.items);

    return {
      ...page,
      items: hydratedItems,
    };
  }

  async getDealById(id: string): Promise<DealDetailResponse> {
    const deal = await this.getDealEntityById(id);
    const hydratedDeals = await this.hydrateDeals([deal]);
    return hydratedDeals[0];
  }

  async transitionDealStage(
    id: string,
    dto: TransitionDealStageDto,
  ): Promise<DealResponse> {
    return this.updateDeal(id, { stage: dto.stage });
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealResponse> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const hasStageMutation = Object.prototype.hasOwnProperty.call(dto, 'stage');
    const existingDeal = await this.getDealEntityById(
      id,
      hasStageMutation
        ? BUSINESS_ERROR_CODES.NOT_FOUND
        : BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
    );

    const targetCompanyId = dto.companyId ?? existingDeal.companyId;
    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.companyService.getCompanyById(dto.companyId);
    }

    const existingLinks = await this.getRawLinksByDealIds([id]);
    const hasContactLinkMutation =
      Object.prototype.hasOwnProperty.call(dto, 'contactLinks') ||
      Object.prototype.hasOwnProperty.call(dto, 'primaryContactId');

    const nextLinks = hasContactLinkMutation
      ? this.resolveUpdatedContactLinks(
          dto,
          existingDeal.primaryContactId,
          existingLinks[id] ?? [],
        )
      : {
          primaryContactId: existingDeal.primaryContactId,
          contactLinks: (existingLinks[id] ?? []).map((link) => ({
            contactId: link.contactId,
            role: link.role,
          })),
        };

    await this.validateContactsForCompany(
      nextLinks.contactLinks.map((link) => link.contactId),
      targetCompanyId,
    );

    const nextExpectedCloseDate = Object.prototype.hasOwnProperty.call(
      dto,
      'expectedCloseDate',
    )
      ? (dto.expectedCloseDate ?? null)
      : existingDeal.expectedCloseDate;

    const nextStage = hasStageMutation
      ? this.resolveRequestedStage(dto.stage)
      : existingDeal.stage;

    if (hasStageMutation) {
      this.validateStageTransition({
        currentStage: this.resolveStoredStage(existingDeal.stage),
        targetStage: nextStage,
        linkedContactCount: nextLinks.contactLinks.length,
        expectedCloseDate: nextExpectedCloseDate,
      });
    }

    const { contactLinks, primaryContactId, ...dealPatch } = dto;

    void contactLinks;
    void primaryContactId;

    await this.dealRepository.manager.transaction(async (entityManager) => {
      const dealRepository = entityManager.getRepository(DealEntity);

      const updatedDeal = dealRepository.merge(existingDeal, {
        ...dealPatch,
        primaryContactId: nextLinks.primaryContactId,
        stage: nextStage,
        expectedCloseDate: nextExpectedCloseDate,
      });

      await dealRepository.save(updatedDeal);

      if (hasContactLinkMutation) {
        await entityManager
          .createQueryBuilder()
          .delete()
          .from('deal_contacts')
          .where('"dealId" = :dealId', { dealId: id })
          .execute();

        if (nextLinks.contactLinks.length > 0) {
          await entityManager
            .createQueryBuilder()
            .insert()

          .insert()
          .into('deal_contacts')
          .values(
            nextLinks.contactLinks.map((link) => ({
              dealId: id,
              contactId: link.contactId,
              role: link.role,
            })),
          )
          .execute();
      }
    }
  });

  return this.getDealById(id);
}

async removeDeal(id: string): Promise<void> {
  await this.getDealEntityById(id);
  await this.dealRepository.softDelete(id);
}

private async getDealEntityById(
  id: string,
  notFoundCode: typeof BUSINESS_ERROR_CODES.NOT_FOUND | typeof BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND =
    BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
): Promise<DealEntity> {
  const deal = await this.dealRepository.findOne({ where: { id } });

  if (!deal) {
    throw new AppException({
      statusCode: HttpStatus.NOT_FOUND,
      code: notFoundCode,
      message: `Deal with ID ${id} not found`,
      details: {
        resource: 'Deal',
        id,
      },
    });
  }

  return deal;
}

private resolveInitialStage(requestedStage: string | undefined): DealStage {
  if (requestedStage === undefined) {
    return 'lead';
  }

  const stage = this.resolveRequestedStage(requestedStage);

  if (!DEAL_INITIAL_STAGE_SET.has(stage)) {
    throw this.invalidInitialStageError(stage);
  }

  return stage;
}

private resolveStoredStage(stage: string): DealStage {
  if (isDealStage(stage)) {
    return stage;
  }

  throw new AppException({
    statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
    code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
    message: `Deal is currently in an invalid stage value "${stage}".`,
    details: {
      currentStage: stage,
    },
  });
}

private resolveRequestedStage(requestedStage: string | undefined): DealStage {
  const normalizedStage = requestedStage?.trim();

  if (!normalizedStage || !isDealStage(normalizedStage)) {
    throw this.unknownStageError(requestedStage);
  }

  return normalizedStage;
}

private validateStageTransition(options: {
  currentStage: DealStage;
  targetStage: DealStage;
  linkedContactCount: number;
  expectedCloseDate: Date | null;
}): void {
  const {
    currentStage,
    targetStage,
    linkedContactCount,
    expectedCloseDate,
  } = options;

  if (currentStage === targetStage) {
    return;
  }

  const allowedTargets = DEAL_STAGE_TRANSITIONS[currentStage];
  if (!allowedTargets.includes(targetStage)) {
    throw this.invalidStageTransitionError({
      currentStage,
      targetStage,
      allowedTargets,
    });
  }

  if (targetStage === 'active' && linkedContactCount < 1) {
    throw this.transitionPreconditionUnmetError(
      targetStage,
      'Transitioning to active requires at least one linked contact.',
    );
  }

  if (targetStage === 'negotiation' && !expectedCloseDate) {
    throw this.transitionPreconditionUnmetError(
      targetStage,
      'Transitioning to negotiation requires expectedCloseDate.',
    );
  }
}

private unknownStageError(requestedStage: string | undefined): AppException {
  const stageValue = requestedStage ?? '';
  const message = `Unknown deal stage "${stageValue}".`;

  return new AppException({
    statusCode: HttpStatus.BAD_REQUEST,
    code: BUSINESS_ERROR_CODES.UNKNOWN_STAGE,
    message,
    details: {
      errors: [
        {
          field: 'stage',
          messages: [message],
        },
      ],
      allowedStages: DEAL_STAGES,
    },
  });
}

private invalidInitialStageError(stage: DealStage): AppException {
  const message =
    'Initial stage must be one of: lead, qualified. Received: ' +
    `"${stage}".`;

  return new AppException({
    statusCode: HttpStatus.BAD_REQUEST,
    code: BUSINESS_ERROR_CODES.INVALID_INITIAL_STAGE,
    message,
    details: {
      errors: [
        {
          field: 'stage',
          messages: [message],
        },
      ],
      allowedInitialStages: DEAL_INITIAL_STAGES,
    },
  });
}

private invalidStageTransitionError(options: {
  currentStage: DealStage;
  targetStage: DealStage;
  allowedTargets: DealStage[];
}): AppException {
  const { currentStage, targetStage, allowedTargets } = options;
  const message =
    `Cannot transition deal stage from "${currentStage}" to "${targetStage}".`;

  return new AppException({
    statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
    code: BUSINESS_ERROR_CODES.INVALID_STAGE_TRANSITION,
    message,
    details: {
      currentStage,
      targetStage,
      allowedTargets,
    },
  });
}

private transitionPreconditionUnmetError(
  targetStage: DealStage,
  reason: string,
): AppException {
  return new AppException({
    statusCode: HttpStatus.UNPROCESSABLE_ENTITY,
    code: BUSINESS_ERROR_CODES.TRANSITION_PRECONDITION_UNMET,
    message: reason,
    details: {
      targetStage,
    },
  });
}

