              onChange={handleChange('value')}
              onBlur={handleBlur('value')}
              error={touched.value && Boolean(errors.value)}
              helperText={touched.value ? errors.value : undefined}
            />

            {isCreateMode ? (
              <TextField
                fullWidth
                select
                label=\"Initial Stage\"
                value={values.stage}
                onChange={handleChange('stage')}
                error={Boolean(stageFieldErrorMessage)}
                helperText={stageFieldErrorMessage || 'Choose lead or qualified.'}
              >
                {DEAL_INITIAL_STAGES.map((stage) => (
                  <MenuItem key={stage} value={stage}>
                    {formatDealStageLabel(stage)}
                  </MenuItem>
                ))}
              </TextField>
            ) : (
              <TextField
                fullWidth
                label=\"Current Stage\"
                value={formatDealStageLabel(values.stage)}
                disabled
              />
            )}
          </Stack>

          {"'!isCreateMode ? (
            stageTransitionTargets.length > 0 ? (
              <TextField
                fullWidth
                select
                label="Transition Stage"
                value={values.targetStage}
                onChange={handleChange('"'targetStage')}
                error={Boolean(stageFieldErrorMessage)}
                helperText={stageFieldErrorMessage || 'Select the next valid stage.'}
              >
                <MenuItem value=\"\">No stage change</MenuItem>
                {stageTransitionTargets.map((stage) => (
                  <MenuItem key={stage} value={stage}>
                    {formatDealStageLabel(stage)}
                  </MenuItem>
                ))}
              </TextField>
            ) : (
              <TextField
                fullWidth
                label=\"Transition Stage\"
                value=\"No transitions available from current stage\"
                disabled
              />
            )
          ) : null}

          <TextField
            fullWidth
            required={isNegotiationTarget}
            label=\"Expected Close Date\"
            type=\"datetime-local\"
            InputLabelProps={{ shrink: true }}
            value={values.expectedCloseDate}
            onChange={handleChange('expectedCloseDate')}
            onBlur={handleBlur('expectedCloseDate')}
            error={touched.expectedCloseDate && Boolean(errors.expectedCloseDate)}
            helperText={touched.expectedCloseDate ? errors.expectedCloseDate : undefined}
          />

          {"'!isCreateMode && initialValues?.createdAt ? (
            <TextField
              disabled
              label="Created At"
              value={new Intl.DateTimeFormat('"'en', {
                dateStyle: 'medium',
                timeStyle: 'short',
              }).format(new Date(initialValues.createdAt))}
            />
