async function hasColumn(
  dataSource: DataSource,
  tableName: string,
  columnName: string,
): Promise<boolean> {
  const [row] = await dataSource.query(
    `
      SELECT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_schema = 'public'
          AND table_name = $1
          AND column_name = $2
      ) AS "exists"
    `,
    [tableName, columnName],
  );

  return Boolean(row?.exists);
}

async function hasTable(
  dataSource: DataSource,
  tableName: string,
): Promise<boolean> {
  const [row] = await dataSource.query(
    `
      SELECT EXISTS (
        SELECT 1
        FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name = $1
      ) AS "exists"
    `,
    [tableName],
  );

  return Boolean(row?.exists);
}

async function undoAppliedMigrations(
  dataSource: DataSource,
  count: number,
): Promise<void> {
  for (let migrationIndex = 0; migrationIndex < count; migrationIndex += 1) {
    await dataSource.undoLastMigration();
  }
}

import { Type } from 'class-transformer';
import {
  IsArray,
  IsDate,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  MaxLength,
  Min,
  ValidateNested,
} from 'class-validator';

export class DealContactLinkInputDto {
  @IsUUID('4', { message: 'contactId must be a valid UUID' })
  contactId!: string;

  @IsOptional()
  @IsString()
  @MaxLength(100)
  role?: string | null;
}

export class CreateDealDto {
  @IsUUID('4', { message: 'companyId must be a valid UUID' })
  companyId!: string;

  @IsOptional()
  @IsArray()
  @ValidateNested({ each: true })
  @Type(() => DealContactLinkInputDto)
  contactLinks?: DealContactLinkInputDto[];

  @IsOptional()
  @IsUUID('4', { message: 'primaryContactId must be a valid UUID' })
  primaryContactId?: string | null;

  @IsString()
  @IsNotEmpty()
  @MaxLength(255)
  name!: string;

  @Type(() => Number)
  @IsNumber()
  @Min(0)
  value!: number;

  @IsString()
  @MaxLength(100)
  @IsOptional()
  stage?: string;

  @IsOptional()
  @Type(() => Date)
  @IsDate()
  expectedCloseDate?: Date | null;
}

